fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool {
    // Each special guest needs one cookie from each pile:
    // so each pile must have at least `m` cookies.
    if a < m || b < m {
        return false;
    }

    // Total cookies needed = n (regular guests) + 2*m (special guests)
    // Use a wider integer type to avoid overflow when adding u8 values.
    let total_available = a as u16 + b as u16;
    let total_needed    = n as u16 + 2 * (m as u16);

    total_available >= total_needed
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_cases() {
        // Not enough cookies for special requirement in one pile
        assert_eq!(solve_cookie_distribution(1, 5, 2, 2), false);
        assert_eq!(solve_cookie_distribution(5, 1, 2, 2), false);

        // Enough in each pile for special guests, but not enough total
        assert_eq!(solve_cookie_distribution(3, 3, 4, 2), false);

        // Exactly enough cookies
        assert_eq!(solve_cookie_distribution(3, 3, 2, 2), true); // total 6 avail, need 2 + 4 = 6

        // More than enough cookies
        assert_eq!(solve_cookie_distribution(10, 5, 4, 3), true);
        assert_eq!(solve_cookie_distribution(0, 0, 0, 0), true);
    }
}